    // 1. Fungsi Helper: Jeda waktu acak (dalam detik)
    const sleep = (min, max) => {
        const ms = (Math.random() * (max - min) + min) * 1000;
        return new Promise(resolve => setTimeout(resolve, ms));
    };

    // 2. Fungsi: Cek dan Klik Tombol Cookie (jika ada)
    const checkAndAcceptCookies = () => {
        const keywords = ['accept all', 'accept cookies', 'terima semua', 'allow all', 'mengerti', 'got it', 'i accept', 'setuju', 'allow cookies'];

        const selectors = [
            'button[id*="cookie" i][id*="accept" i]',
            'button[class*="cookie" i][class*="accept" i]',
            'button[id*="consent" i]',
            'button[class*="consent" i]',
            '[aria-label*="accept cookie" i]'
        ];

        for (let selector of selectors) {
            const elements = document.querySelectorAll(selector);
            for (let el of elements) {
                if (el && el.offsetHeight > 0 && el.offsetWidth > 0) {
                    el.click();
                    console.log("[-] Cookie consent diklik (via selector).");
                    return;
                }
            }
        }

        const buttons = document.querySelectorAll('button, a');
        for (let btn of buttons) {
            if (btn && btn.offsetHeight > 0 && btn.offsetWidth > 0) {
                const text = btn.innerText.toLowerCase().trim();
                if (keywords.some(kw => text === kw || text.includes(kw))) {
                    btn.click();
                    console.log("[-] Cookie consent diklik (via teks).");
                    return;
                }
            }
        }
    };

    // 3. Fungsi: Simulasi pergerakan mouse ke koordinat acak
    const simulateMouseMovement = () => {
        const x = Math.floor(Math.random() * window.innerWidth);
        const y = Math.floor(Math.random() * window.innerHeight);
        const ev = new MouseEvent('mousemove', {
            view: window,
            bubbles: true,
            cancelable: true,
            clientX: x,
            clientY: y
        });
        document.dispatchEvent(ev);
        console.log(`[-] Mouse bergerak ke: X=${x}, Y=${y}`);
    };

    // 4. Fungsi: Simulasi Scroll (lebih sering ke bawah daripada ke atas)
    const randomScroll = () => {
        const isScrollingDown = Math.random() > 0.3; 
        const direction = isScrollingDown ? 1 : -1; 

        // Jarak scroll acak antara 150px hingga 500px
        const distance = Math.floor(Math.random() * 350) + 150; 

        window.scrollBy({
            top: direction * distance,
            left: 0,
            behavior: 'smooth'
        });
        console.log(`[-] Scroll ${isScrollingDown ? 'ke bawah' : 'ke atas'} sejauh ${distance}px`);
    };

    // 5. Fungsi Utama yang berjalan di latar belakang (tanpa menahan Automa)
    async function runBackgroundInteraction() {
        try {
            // Durasi acak antara 60 detik (1 menit) hingga 120 detik (2 menit)
            const interactionDurationMs = (Math.random() * (120 - 60) + 60) * 1000; 
            const startTime = Date.now();

            console.log(`[-] Memulai simulasi interaksi manusia selama ${(interactionDurationMs / 1000).toFixed(2)} detik...`);

            // Cek cookie di awal halaman
            checkAndAcceptCookies();

            // Looping interaksi selama durasi waktu belum habis
            while (Date.now() - startTime < interactionDurationMs) {
                const action = Math.floor(Math.random() * 3);

                if (action === 0) {
                    randomScroll();
                } else if (action === 1) {
                    simulateMouseMovement();
                } else {
                    checkAndAcceptCookies();
                }

                // Jeda antar tindakan agar terlihat natural (antara 1.5 hingga 4.5 detik)
                await sleep(1.5, 4.5);
            }

            console.log("[-] Simulasi interaksi manusia selesai.");

        } catch (error) {
            console.error("[-] Terjadi error pada script interaksi:", error);
        }
    }

    // ==========================================
    // EKSEKUSI FIRE AND FORGET
    // ==========================================

    // 1. Jalankan fungsi interaksi (Tanpa 'await' agar tidak menunggu)
    runBackgroundInteraction();

    // 2. Langsung lanjutkan ke node Automa berikutnya detik ini juga!
    automaNextBlock();
})();","context":"website","description":"interaksi di iklan","disableBlock":false,"everyNewTab":false,"preloadScripts":[],"runBeforeLoad":false,"timeout":20000},"label":"javascript-code"},{"id":"hubws6u","type":"BlockBasic","initialized":false,"position":{"x":2251.7427850216022,"y":-1452.7577507926874},"data":{"activeTab":true,"allWindows":false,"closeType":"tab","description":"close TAB","disableBlock":false,"url":""},"label":"close-tab"},{"id":"gzekytj","type":"BlockDelay","initialized":false,"position":{"x":1255.4955627652676,"y":-1235.244983156587},"data":{"disableBlock":false,"time":"3000"},"label":"delay"},{"id":"5r2gie5","type":"BlockBasic","initialized":false,"position":{"x":1810.075111016627,"y":-1220.2980874368116},"data":{"action":"press-key","description":"play iklan","disableBlock":false,"keys":"k","keysToPress":"","pressTime":"0","selector":""},"label":"press-key"},{"id":"xj1l4ur","type":"BlockBasic","initialized":false,"position":{"x":2235.6485353752264,"y":-861.120957029999},"data":{"description":"","disableBlock":false,"increaseBy":1,"variableName":"counter_video"},"label":"increase-variable"},{"id":"mgfxptx","type":"BlockDelay","initialized":false,"position":{"x":1245.8910721503962,"y":-943.3593276941485},"data":{"disableBlock":false,"time":"10000"},"label":"delay"},{"id":"dtdggzg","type":"BlockBasic","initialized":false,"position":{"x":2866.5322910520126,"y":-1941.4171742620574},"data":{"action":"press-key","description":"NEXTvideo selanjutnya","disableBlock":false,"keys":"Shift+N","keysToPress":"","pressTime":"0","selector":"","settings":{"blockTimeout":0,"debugMode":true}},"label":"press-key"},{"id":"ei3t57r","type":"BlockBasic","initialized":false,"position":{"x":3479.63358376125,"y":-1025.0262011249858},"data":{"code":"alert("TUGAS SELESAI")
