    const checkAndAcceptCookies = () => {
        const keywords = ['accept all', 'accept cookies', 'terima semua', 'allow all', 'mengerti', 'got it', 'i accept', 'setuju', 'allow cookies'];

        const selectors = [
            'button[id*="cookie" i][id*="accept" i]',
            'button[class*="cookie" i][class*="accept" i]',
            'button[id*="consent" i]',
            'button[class*="consent" i]',
            '[aria-label*="accept cookie" i]'
        ];

        for (let selector of selectors) {
            const elements = document.querySelectorAll(selector);
            for (let el of elements) {
                if (el && el.offsetHeight > 0 && el.offsetWidth > 0) {
                    el.click();
                    console.log("[-] Cookie consent diklik (via selector).");
                    return;
                }
            }
        }

        const buttons = document.querySelectorAll('button, a');
        for (let btn of buttons) {
            if (btn && btn.offsetHeight > 0 && btn.offsetWidth > 0) {
                const text = btn.innerText.toLowerCase().trim();
                if (keywords.some(kw => text === kw || text.includes(kw))) {
                    btn.click();
                    console.log("[-] Cookie consent diklik (via teks).");
                    return;
                }
            }
        }
    };

    // 3. Fungsi: Simulasi pergerakan mouse ke koordinat acak
    const simulateMouseMovement = () => {
        const x = Math.floor(Math.random() * window.innerWidth);
        const y = Math.floor(Math.random() * window.innerHeight);
        const ev = new MouseEvent('mousemove', {
            view: window,
            bubbles: true,
            cancelable: true,
            clientX: x,
            clientY: y
