    const randomScroll = () => {
        const isScrollingDown = Math.random() > 0.3; 
        const direction = isScrollingDown ? 1 : -1; 

        // Jarak scroll acak antara 150px hingga 500px
        const distance = Math.floor(Math.random() * 350) + 150; 

        window.scrollBy({
            top: direction * distance,
            left: 0,
            behavior: 'smooth'
        });
        console.log(`[-] Scroll ${isScrollingDown ? 'ke bawah' : 'ke atas'} sejauh ${distance}px`);
    };

